import type { ConfigService } from '@nestjs/config';
import { ReceiptService, formatReceiptDate } from './receipt.service';

/**
 * The receipt PDF is generated by the API, not the browser, so its dates must
 * not depend on the host's timezone: the production image is UTC while the
 * college and its students are on Addis Ababa time (UTC+3, no DST).
 *
 * These tests run with TZ=UTC (the production container default) so a
 * timezone-agnostic implementation fails here instead of on the live server.
 */
describe('receipt date formatting', () => {
  it('formats an entitlement instant on the Addis Ababa calendar day', () => {
    // 22:00 UTC on Saturday 30 Jan is already Sunday 31 Jan 01:00 in Addis.
    expect(formatReceiptDate(new Date('2026-01-30T22:00:00.000Z'))).toBe(
      '31/01/2026',
    );
    // ...and 22:00 UTC on the last day of February is 1 March there.
    expect(formatReceiptDate(new Date('2026-02-28T22:00:00.000Z'))).toBe(
      '01/03/2026',
    );
  });

  it('formats the payment timestamp with the Addis time of day', () => {
    expect(formatReceiptDate(new Date('2026-01-30T22:05:00.000Z'), true)).toBe(
      '31/01/2026, 01:05',
    );
  });

  it('keeps the same output whatever the host timezone is', () => {
    const instant = new Date('2026-06-15T21:30:00.000Z');
    // Addis is UTC+3 all year (no DST), so this is 16 June 00:30 there.
    expect(formatReceiptDate(instant)).toBe('16/06/2026');
    expect(formatReceiptDate(instant, true)).toBe('16/06/2026, 00:30');
  });
});

/**
 * The receipt number carries the year the payment belongs to on the college's
 * calendar, not the API host's. Production runs in UTC, so a payment late on
 * New Year's Eve would otherwise be numbered with the previous year while the
 * receipt it prints says the next one.
 */
describe('receipt numbering', () => {
  const service = new ReceiptService({} as ConfigService);

  it('uses the Addis Ababa year just after midnight on 1 January', () => {
    // 21:30 UTC on 31 Dec 2026 is already 00:30 on 1 Jan 2027 in Addis.
    expect(
      service.buildReceiptNumber(
        'payment-abcdefgh',
        new Date('2026-12-31T21:30:00.000Z'),
      ),
    ).toBe('LM-2027-ABCDEFGH');
  });

  it('still uses the old year during the last minute in Addis', () => {
    // 20:59:59 UTC is 23:59:59 on 31 Dec 2026 in Addis.
    expect(
      service.buildReceiptNumber(
        'payment-abcdefgh',
        new Date('2026-12-31T20:59:59.000Z'),
      ),
    ).toBe('LM-2026-ABCDEFGH');
  });
});
